import RNA, random, multiprocessing as mp, time, sys
target = "....((((((((....((..(...................)..(((...((....))...((....))........))).......))))))))))...."
def worker(seed):
    random.seed(seed)
    best_seq, best_d = None, 999
    for _ in range(300):
        start = ''.join(random.choice('ACGU') for _ in range(len(target)))
        seq, d = RNA.inverse_fold(start, target)
        if d == 0:
            f = RNA.fold_compound(seq).mfe()[0]
            if f == target:
                return ('SOLVED', seq)
        if d < best_d:
            best_seq, best_d = seq, d
    return ('best', best_d, best_seq)
if __name__ == '__main__':
    t0 = time.time()
    found = []
    with mp.Pool(64) as p:
        for r in p.imap_unordered(worker, range(400), chunksize=1):
            if r[0]=='SOLVED':
                print("SOLVED", r[1], flush=True)
                found.append(r[1])
                if len(found)>=1:
                    p.terminate(); break
            else:
                pass
    if not found:
        print("no solve", time.time()-t0)
